        if (difference % divisor == 0) {
            if (divisor > b) {
                ++answer;
            }

            long long pairedDivisor = difference / divisor;
            if (pairedDivisor != divisor && pairedDivisor > b) {
                ++answer;
            }
        }
    }

    cout << answer << '\n';
    return 0;
}

